L000057	  \title{Connecting Magic Dynamics in Thermofield Double States to Spectral Form Factors }
L000058	
L000059	
L000060	  \author{Ning Sun}
L000061	  \affiliation{State Key Laboratory of Surface Physics \& Department of Physics, Fudan University, Shanghai, 200438, China}
